function toast(msg, kind = '') { let w = document.querySelector('.toast-wrap'); if (!w) { w = document.createElement('div'); w.className = 'toast-wrap'; w.setAttribute('role', 'status'); w.setAttribute('aria-live', 'polite'); document.body.appendChild(w); } const t = document.createElement('div'); t.className = `toast ${kind}`; t.textContent = msg; w.appendChild(t); const ms = Math.min(7000, Math.max(kind === 'err' ? 4500 : 2400, 1200 + String(msg).length * 55)); let tm; const leave = () => { const Mo = root.Motion; if (Mo && Mo.enabled) Mo.leave(t, 'out', '--dur-2', () => t.remove()); else t.remove(); }; const arm = d => { clearTimeout(tm); tm = setTimeout(leave, d); }; t.addEventListener('mouseenter', () => { clearTimeout(tm); t.classList.remove('out'); }); t.addEventListener('mouseleave', () => arm(1500)); arm(ms); }
app.css:898 .toast: `pointer-events: auto;` ergänzen. .toast-wrap (897) behält pointer-events: none, damit die Fläche neben dem Toast weiter Klicks durchlässt.
